CREATE TABLE vino."Clientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CriadoEm" timestamp with time zone NOT NULL,
    "Nome" text NOT NULL,
    "CpfCnpj" character varying(14),
    "Email" character varying(150),
    "Telefone" text,
    "DataNascimento" date,
    "SenhaHash" text,
    "Endereco_Cep" text,
    "Endereco_Logradouro" text,
    "Endereco_Numero" text,
    "Endereco_Complemento" text,
    "Endereco_Bairro" text,
    "Endereco_Cidade" text,
    "Endereco_Uf" text,
    "AceitaMarketing" boolean NOT NULL,
    "Ativo" boolean NOT NULL,
    CONSTRAINT "PK_Clientes" PRIMARY KEY ("Id")
);
CREATE UNIQUE INDEX "IX_Clientes_Email" ON vino."Clientes" ("Email");
CREATE INDEX "IX_Clientes_CpfCnpj" ON vino."Clientes" ("CpfCnpj");

CREATE TABLE vino."Depositos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CriadoEm" timestamp with time zone NOT NULL,
    "Nome" text NOT NULL,
    "Tipo" character varying(30) NOT NULL,
