    CONSTRAINT "PK_Pedidos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Pedidos_Clientes_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES vino."Clientes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Pedidos_Depositos_DepositoId" FOREIGN KEY ("DepositoId") REFERENCES vino."Depositos" ("Id") ON DELETE RESTRICT
