    "Parcelas" integer NOT NULL,
    "Nsu" character varying(30),
    CONSTRAINT "PK_PagamentosVenda" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PagamentosVenda_Vendas_VendaId" FOREIGN KEY ("VendaId") REFERENCES vino."Vendas" ("Id") ON DELETE CASCADE
);
CREATE INDEX "IX_PagamentosVenda_VendaId" ON vino."PagamentosVenda" ("VendaId");

-- As tabelas pertencem ao papel da aplicação; RLS ligado como defesa extra (o dono não é afetado; ninguém mais tem acesso).
DO $$
DECLARE t record;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'vino' LOOP
    EXECUTE format('ALTER TABLE vino.%I OWNER TO vino_app', t.tablename);
    EXECUTE format('ALTER TABLE vino.%I ENABLE ROW LEVEL SECURITY', t.tablename);
  END LOOP;
END $$;
